  if (x-nx)^2+(y-ny)^2<r*r then return false end
 end
 local hx,hy=M.project(room,x,y,1.8)
 if sx<12 or sx>468 or sy<18 or sy>268 or hx<12 or hx>468 or hy<18 or hy>268 then return false end
 return true
end
function M.inOpening(room,sx,sy,world)
 local x,y=M.ground(room,sx,sy)
 return x>=world[1] and x<=world[2] and y>=world[3] and y<=world[4]
end
function M.towards(room,sx,sy,dx,dy,world)
 local x,y=M.ground(room,sx,sy);local tx,ty=M.ground(room,sx+dx,sy+dy)
 return ((world[6]==1 and tx-x)or ty-y)*world[5]>0
end

